set.seed(20260813);dir.create("data",FALSE);dir.create("output",FALSE);dir.create("figures",FALSE);dir.create("docs",FALSE)
n<-3000;d<-data.frame(id=1:n,age=rnorm(n,62,11),female=rbinom(n,1,.54),comorbidity=rpois(n,2),severity=rnorm(n),prior_admission=rbinom(n,1,.25))
d$ps_true<-with(d,plogis(-.3+.025*(age-62)+.25*female+.28*comorbidity+.65*severity+.5*prior_admission));d$treatment<-rbinom(n,1,d$ps_true)
d$outcome<-rbinom(n,1,with(d,plogis(-2.2-.45*treatment+.018*(age-62)+.18*comorbidity+.45*severity+.35*prior_admission)));write.csv(d,"data/observational_cohort.csv",row.names=FALSE)
psfit<-glm(treatment~age+female+comorbidity+severity+prior_admission,data=d,family=binomial());d$ps<-predict(psfit,type="response");p1<-mean(d$treatment);d$sw<-ifelse(d$treatment,p1/d$ps,(1-p1)/(1-d$ps));q<-quantile(d$sw,c(.01,.99));d$sw_trim<-pmin(pmax(d$sw,q[1]),q[2])
wmean<-function(y,w)sum(y*w)/sum(w); ate<-function(w){a<-wmean(d$outcome[d$treatment==1],w[d$treatment==1])-wmean(d$outcome[d$treatment==0],w[d$treatment==0]);se<-sqrt(weighted.mean((d$outcome[d$treatment==1]-wmean(d$outcome[d$treatment==1],w[d$treatment==1]))^2,w[d$treatment==1])/sum(d$treatment==1)+weighted.mean((d$outcome[d$treatment==0]-wmean(d$outcome[d$treatment==0],w[d$treatment==0]))^2,w[d$treatment==0])/sum(d$treatment==0));c(a,se)}
naive<-ate(rep(1,n)); iptw<-ate(d$sw); trim<-ate(d$sw_trim)
ti<-which(d$treatment==1);avail<-which(d$treatment==0);pairs<-matrix(NA_integer_,length(ti),2);lp<-qlogis(d$ps)
for(i in seq_along(ti)){j<-avail[which.min(abs(lp[avail]-lp[ti[i]]))];pairs[i,]<-c(ti[i],j);avail<-avail[avail!=j];if(!length(avail)){pairs<-pairs[seq_len(i),,drop=FALSE];break}}
md<-d$outcome[pairs[,1]]-d$outcome[pairs[,2]];match_est<-c(mean(md),sd(md)/sqrt(length(md)))
out<-data.frame(method=c("Unadjusted","Stabilized IPTW","IPTW trimmed at 1st/99th percentiles","1:1 propensity-score matching (ATT)"),risk_difference=c(naive[1],iptw[1],trim[1],match_est[1]),se=c(naive[2],iptw[2],trim[2],match_est[2]));out$lower<-out$risk_difference-1.96*out$se;out$upper<-out$risk_difference+1.96*out$se;write.csv(out,"output/effect_estimates.csv",row.names=FALSE)
smd<-function(v,w){m1<-wmean(v[d$treatment==1],w[d$treatment==1]);m0<-wmean(v[d$treatment==0],w[d$treatment==0]);(m1-m0)/sqrt((var(v[d$treatment==1])+var(v[d$treatment==0]))/2)};vars<-c("age","female","comorbidity","severity","prior_admission");bal<-data.frame(variable=vars,before=sapply(d[vars],smd,w=rep(1,n)),after=sapply(d[vars],smd,w=d$sw_trim));write.csv(bal,"output/covariate_balance.csv",row.names=FALSE)
bp<-reshape(bal,direction="long",varying=c("before","after"),v.names="smd",timevar="stage",times=c("Before","After"));p<-ggplot2::ggplot(bp,ggplot2::aes(abs(smd),variable,color=stage))+ggplot2::geom_point(size=3)+ggplot2::geom_vline(xintercept=.1,linetype=2)+ggplot2::labs(title="Covariate Balance Before and After IPTW",x="Absolute standardized mean difference",y=NULL,color=NULL)+ggplot2::theme_minimal(base_size=12);ggplot2::ggsave("figures/love-plot.png",p,width=7,height=4.5,dpi=160)
stopifnot(all(d$ps>0&d$ps<1),max(abs(bal$after))<max(abs(bal$before)),out$risk_difference[3]<0)
html<-sprintf('<!doctype html><meta charset="utf-8"><style>body{font:16px Arial;max-width:900px;margin:40px auto;color:#111;line-height:1.5}img{max-width:100%%}</style><h1>Causal Inference in Observational Health Data</h1><p><b>Question:</b> What is the average treatment effect on the risk of the clinical outcome after controlling measured confounding?</p><h2>Methods</h2><p>A prespecified logistic propensity-score model used age, sex, comorbidity, severity, and prior admission. Stabilized inverse-probability weights target the ATE; percentile trimming evaluates sensitivity to extreme weights. Balance is assessed with standardized mean differences.</p><h2>Result</h2><p>Trimmed IPTW risk difference: <b>%.3f</b> (95%% CI %.3f to %.3f).</p><img src="../figures/love-plot.png"><h2>Interpretation</h2><p>The estimate is conditional on consistency, positivity, correct propensity-score specification, and no unmeasured confounding. The balance plot is a design diagnostic, not proof that these assumptions hold.</p><h2>Reproducibility</h2><p>Run <code>Rscript run_all.R</code>. Data are synthetic.</p>',out$risk_difference[3],out$lower[3],out$upper[3]);writeLines(html,"docs/index.html")
